5	import jakarta.persistence.GeneratedValue;
6	import jakarta.persistence.GenerationType;
7	import jakarta.persistence.Id;
8	import jakarta.persistence.Table;
9	
10	/**
11	 * A checklist item on a project: a title, the id of the project it belongs to, and whether it is
12	 * done. Persisted to the {@code tasks} table (Flyway V12). The id is database-generated (IDENTITY)
13	 * on create; the seed path inserts explicit ids directly via JdbcTemplate (see
14	 * {@link TestSupportController}). A task is OPEN while {@code done} is false and DONE once ticked off.
15	 */
16	@Entity
17	@Table(name = "tasks")
